import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const packageUrl = new URL("../package.json", import.meta.url);
const outputUrl = new URL("../src/version.gen.ts", import.meta.url);
const { version } = JSON.parse(readFileSync(packageUrl, "utf8"));
if (
  typeof version !== "string" ||
  !/^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/u.test(version)
) {
  throw new TypeError("@neon/realtime requires a stable SemVer package version");
}

const source = [
  "// Generated by packages/realtime/scripts/generate-version.mjs. Do not edit.",
  `export const REALTIME_CLIENT_VERSION = ${JSON.stringify(version)} as const;`,
  "",
].join("\n");

if (process.argv.includes("--check")) {
  let checkedInSource;
  try {
    checkedInSource = readFileSync(outputUrl, "utf8");
  } catch {
    checkedInSource = undefined;
  }
  if (checkedInSource !== source) {
    console.error(
      `${fileURLToPath(outputUrl)} is stale; run npm run generate:version --workspace @neon/realtime`,
    );
    process.exitCode = 1;
  }
} else {
  writeFileSync(outputUrl, source);
}
